INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_VENDIDAD','primary text','Vendidad (Videvdad, ''Law against the Demons''), Younger Avesta, ed./trans. J. Darmesteter, SBE 4','Zoroastrian law, eschatology, and cosmography incl. the Chinvat Bridge and post-mortem realms'),
 ('SRC_DESCENT_ISHTAR','primary text','The Descent of Ishtar to the Netherworld (Akkadian), trans. S. Dalley, Myths from Mesopotamia (Oxford University Press, 2000)','Mesopotamian netherworld (Irkalla/Kur), its gates, and Ereshkigal''s rule'),
 ('SRC_HEKHALOT_RABBATI','primary text','Hekhalot Rabbati (''The Greater Palaces''), Merkavah text, ed. in P. Schafer, Synopse zur Hekhalot-Literatur','The seven heavenly palaces (hekhalot) and the ascent of the descender to the chariot')
INSERT INTO _e VALUES
 ('ENT_RLMX_CHINVAT','Chinvat Bridge','Cosmological realm','Cosmological realm','Zoroastrian','Eschatology / judgement of the soul','B','The Cinvat (Chinvat) Bridge, the ''bridge of the separator/accountant'' which every soul must cross after death; attested in the Gathas (Y. 46.10, 51.13) and the Vendidad (19), where Rashnu, Mithra and Sraosha judge and the Daena meets the soul. Widens for the righteous, narrows to a blade for the wicked.'),
 ('ENT_RLMX_GAROTHMAN','Garothman (House of Song)','Cosmological realm','Cosmological realm','Zoroastrian','Paradise / best existence','B','Garothman / Garodman, the ''House of Song'' (Avestan Garo-demana), the highest paradise and abode of Ahura Mazda and the blessed (the ''Best Existence'', vahishta ahu). Attested in the Avesta and elaborated in the Bundahishn and Menog-i Khrad.'),
 ('ENT_RLMX_DRUJO_DEMANA','Drujo Demana (House of Lies)','Cosmological realm','Cosmological realm','Zoroastrian','Hell / worst existence','B','Drujo Demana, the ''House of the Lie'' (Avestan druj-demana), the Zoroastrian hell and abode of Angra Mainyu and the damned (the ''Worst Existence''). Antithesis of the House of Song; attested in the Gathas (Y. 46.11, 49.11) and Pahlavi eschatology.'),
 ('ENT_RLMX_HAMISTAGAN','Hamistagan','Cosmological realm','Cosmological realm','Zoroastrian','Limbo / neutral intermediate state','B','Hamistagan (Pahlavi hammistagan), the neutral ''place of the mixed'', an intermediate state for souls whose good and evil deeds are exactly balanced; they remain there, untormented but joyless, until the final renovation (Frashokereti). Attested in the Bundahishn and Menog-i Khrad.'),
 ('ENT_RLMX_IRKALLA','Irkalla (Kur)','Cosmological realm','Cosmological realm','Mesopotamian','Netherworld / land of the dead','B','Irkalla (Sumerian Kur, the ''land of no return''), the Mesopotamian underworld ruled by Ereshkigal (and Nergal), a dark dust-filled realm where the dead eat clay. Attested in the Descent of Ishtar and the Descent of Inanna. NOTE: distinct from the being Apsu (ENT_MES_APSU); this is the place.'),
 ('ENT_RLMX_GANZIR','Ganzir','Cosmological realm','Cosmological realm','Mesopotamian','Gate of the netherworld','C','Ganzir, the gate / threshold (the ''face'') of the netherworld Irkalla/Kur, sometimes used as a name for the underworld''s entrance through which the dead pass the seven gates. Attested in the Descent of Inanna/Ishtar tradition.'),
 ('ENT_RLMX_DILMUN','Dilmun','Cosmological realm','Cosmological realm','Mesopotamian','Pure land / paradise','B','Dilmun, the ''pure, clean, bright'' land where there is no death or sickness, watered with fresh water by Enki; the Sumerian paradise (and a real geographical region, Bahrain). Attested in the myth Enki and Ninhursag.'),
 ('ENT_RLMX_SEVEN_HEAVENS','The Seven Heavens (Vilon, Raqia, Shehaqim, Zebul, Maon, Makhon, Araboth)','Cosmological structure','Cosmological structure','Jewish Mystical','Vertical celestial cosmography','B','The seven heavens of rabbinic/Merkavah cosmology, named in b. Hagigah 12b: Vilon, Raqia, Shehaqim, Zebul, Maon, Makhon, and Araboth (the highest, housing the Throne of Glory). Distinct from the seven firmaments of Sefer ha-Razim.'),
 ('ENT_RLMX_SEVEN_HEKHALOT','The Seven Hekhalot (Heavenly Palaces)','Cosmological structure','Cosmological structure','Jewish Mystical','Merkavah ascent / celestial palaces','B','The seven hekhalot (''palaces''/''halls'') nested within the highest heaven (Araboth), each guarded by angelic gatekeepers, through which the yored merkavah (''descender to the chariot'') ascends to the Throne. Attested in Hekhalot Rabbati.');
